import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"How does the adapter calculate?","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/05.hintergrund/01.berechnung.md"},"headers":[],"relativePath":"adapter/sourceanalytix/hintergrund/berechnung.md","filePath":"adapter/sourceanalytix/hintergrund/berechnung.md","lastUpdated":null}'),n={name:"adapter/sourceanalytix/hintergrund/berechnung.md"};function s(i,e,d,l,h,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="how-does-the-adapter-calculate" tabindex="-1">How does the adapter calculate? <a class="header-anchor" href="#how-does-the-adapter-calculate" aria-label="Permalink to &quot;How does the adapter calculate?&quot;">​</a></h1><p><a id="sourceanalytix-still-maintained"></a></p><h2 id="is-sourceanalytix-still-being-developed" tabindex="-1">Is SourceAnalytix still being developed? <a class="header-anchor" href="#is-sourceanalytix-still-being-developed" aria-label="Permalink to &quot;Is SourceAnalytix still being developed?&quot;">​</a></h2><p>Yes. New versions come out regularly, currently in the &quot;latest&quot; repository. SourceAnalytix moves to &quot;stable&quot; after a test phase.</p><p>For questions and bugs:</p><ol><li>First look at the &quot;Problems&quot; tab of the instance settings. It checks all sources and suggests a fix.</li><li>Read the <a href="./../fehlerbehebung/">troubleshooting</a> pages.</li><li>Report a bug or wish as an issue in the <a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues" target="_blank" rel="noreferrer">GitHub repository</a>, with the versions of SourceAnalytix, js-controller and Node.js and the source&#39;s log.</li></ol><p><a id="values-differ-meter-portal-evcc"></a></p><h2 id="why-do-the-values-differ-from-my-meter-portal-or-evcc" tabindex="-1">Why do the values differ from my meter, portal or evcc? <a class="header-anchor" href="#why-do-the-values-differ-from-my-meter-portal-or-evcc" aria-label="Permalink to &quot;Why do the values differ from my meter, portal or evcc?&quot;">​</a></h2><p>Usually for one of four reasons: the source is a power value that rarely sends, the portal assigns consumption to a different time, the device measures differently from your meter, or start values and unit don&#39;t fit.</p><table tabindex="0"><thead><tr><th>Cause</th><th>How to recognise it</th><th>What helps</th></tr></thead><tbody><tr><td>power (W) that only sends every few minutes</td><td>large deviation</td><td>use a total counter in kWh or make it send more often</td></tr><tr><td>a pause of a power source</td><td>consumption is missing or too high after an outage</td><td>&quot;Maximum gap between power values (minutes)&quot;</td></tr><tr><td>assigned to a different time</td><td>days differ, the sum over several days matches</td><td>nothing, both are right</td></tr><tr><td>the device measures differently, e.g. a Shelly 3EM per phase</td><td>doesn&#39;t match the meter in the basement</td><td>read the meter itself, for example with an optical reading head</td></tr><tr><td>start values, unit or total wrong</td><td>negative, too high or offset</td><td><a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correcting wrong values</a></td></tr></tbody></table><p>SourceAnalytix books consumption on the day it was measured. A wallbox or evcc often books a whole charging session on the day it ends. Over several days this evens out.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Meter or power?</a></p><p><a id="sourceanalytix-convert-watts-kwh"></a></p><h2 id="how-does-sourceanalytix-convert-watts-to-kwh" tabindex="-1">How does SourceAnalytix convert watts to kWh? <a class="header-anchor" href="#how-does-sourceanalytix-convert-watts-to-kwh" aria-label="Permalink to &quot;How does SourceAnalytix convert watts to kWh?&quot;">​</a></h2><p>With every new value: the previous power times the time since the previous value. With &quot;Average power values&quot;, SourceAnalytix uses the average of the previous and the new value. The energy is added to the total.</p><table tabindex="0"><thead><tr><th>Time</th><th>Value</th><th>without average</th><th>with average</th></tr></thead><tbody><tr><td>10:00</td><td>0 W</td><td>starting point</td><td>starting point</td></tr><tr><td>10:30</td><td>1,000 W</td><td>0 Wh</td><td>250 Wh</td></tr><tr><td>11:00</td><td>1,000 W</td><td>500 Wh</td><td>500 Wh</td></tr><tr><td>Total</td><td></td><td>0.5 kWh</td><td>0.75 kWh</td></tr></tbody></table><p>Without the average it suits devices that switch abruptly and only send on change; with the average, sensors that send regularly. It calculates on every written value, even if it stays the same; the last value applies until the next one.</p><p>Pauses:</p><ul><li>The first value after activation or a restart is only the starting point.</li><li>If no value arrives for a long time, the last one is extrapolated, unless &quot;Maximum gap between power values (minutes)&quot; is set.</li><li>At midnight, the energy up to 0:00 is booked to the old day.</li></ul><p>Each stretch is priced at the price that applied at the time of the value.</p><p><strong>See also:</strong> <a href="./../anleitungen/quellen-und-einheiten#sourceanalytix-compute-consumption-meter-reading">Can SourceAnalytix calculate consumption from power?</a></p><p><a id="consumption-calculated-currentyear-lower-than"></a></p><h2 id="how-is-consumption-calculated-and-why-is-currentyear-lower-than-my-meter-reading" tabindex="-1">How is consumption calculated, and why is currentYear lower than my meter reading? <a class="header-anchor" href="#how-is-consumption-calculated-and-why-is-currentyear-lower-than-my-meter-reading" aria-label="Permalink to &quot;How is consumption calculated, and why is currentYear lower than my meter reading?&quot;">​</a></h2><p>Because <code>currentYear.consumed.05_currentYear</code> is this year&#39;s consumption, not the meter reading. It is the total minus the &quot;Year&quot; start value. The meter reading is in <code>cumulativeReading</code>.</p><table tabindex="0"><thead><tr><th></th><th>Value</th></tr></thead><tbody><tr><td>Total</td><td>12,480 kWh</td></tr><tr><td>&quot;Year&quot; start value (reading on 1 January)</td><td>11,900 kWh</td></tr><tr><td><code>05_currentYear</code></td><td>580 kWh</td></tr></tbody></table><p>SourceAnalytix sets the start values itself at every period rollover. If you activated during the year, the year counts from that day, unless you enter the reading from 1 January as the <a href="./../erste-schritte/erster-zaehler#start-values-unit">start value</a>.</p><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#meter-readings-cumulative">Meter readings</a></p>',27)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
